def footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(PEACH); canvas.line(18*mm, 14*mm, 192*mm, 14*mm)
    canvas.setFont('Helvetica',7); canvas.setFillColor(MUTED); canvas.drawString(18*mm,9*mm,'BABY COCOON · GOOGLE ADS PLAYBOOK'); canvas.drawRightString(192*mm,9*mm,f'{doc.page}')
    canvas.restoreState()

